 static OperationMapDefinition Source(){string root="Assets/Game/GeneratedOperationMaps/CH05M01CitywideAlert/",text=File.ReadAllText(root+"Definition.asset");var s=Persistent<OperationMapDefinition>(root+"Definition.asset");s.OperationMapId=Field(text,"operationMapId");s.SourceIdentityHash=Field(text,"sourceIdentityHash");s.ContentHash=Field(text,"contentHash");s.GeneratedMetadataHash=Field(text,"generatedMetadataHash");s.Bounds=new OperationMapBoundsConfig{WorldMin=new Vector3(860,-20,300),WorldMax=new Vector3(1300,1000,520),PlayableMin=new Vector3(868,-20,308),PlayableMax=new Vector3(1292,980,512)};s.GridMetadata=new OperationMapGridMetadataConfig{AssetGuid=Sub(text,"gridMetadata","assetGuid"),ContentHash=Sub(text,"gridMetadata","contentHash"),Origin=new Vector3(860,0,300),CellSize=1,AuthoredBlockedCellCount=16392};s.SurfaceMetadata=new OperationMapSurfaceMetadataConfig{AssetGuid=Sub(text,"surfaceMetadata","assetGuid"),ContentHash=Sub(text,"surfaceMetadata","contentHash"),RuntimeBlobHash=Sub(text,"surfaceMetadata","runtimeBlobHash"),SurfaceCount=96800,MinimumHeight=-5.31082f,MaximumHeight=17.199179f};s.NavigationMetadata=new OperationMapNavigationMetadataConfig{AuthoredSubSceneGuid=Sub(text,"navigationMetadata","authoredSubSceneGuid")};s.SourceSceneReference=new AssetRef{AssetGUID=Sub(text,"sourceSceneReference","m_AssetGUID")};s.MapSurfaceDataReference=new AssetRef{AssetGUID=s.SurfaceMetadata.AssetGuid};AssetDatabase.Guids[s.GridMetadata.AssetGuid]=root+"Grid.asset";AssetDatabase.Guids[s.SurfaceMetadata.AssetGuid]=root+"Surface.asset";return s;}
