 {var changed=Layout();string expected=SkirmishMeasuredLayoutBinder.ComputeLayoutSemanticFingerprint(changed);var pad=changed.Pads[0];pad.WidthMetres+=1;changed.Pads[0]=pad;Check(!SkirmishGroundSourceFitSurvey.TryCreateGroundBaLogicalSourceLayoutInput(source,changed,Pins(source),expected,out var rejected,out _)&&rejected==null,"stale full-layout semantic fingerprint rejects raw typed recipe mutation");UnityEngine.Object.DestroyImmediate(changed);}
